function o(n){return n==="inbound_order"?["receiving","qc","putaway","putaway_quarantine","routing","dispatch"]:["pick","pack","dispatch","routing"]}function p(n,e){const r=o(e);return[...n].sort((t,a)=>{const c=r.indexOf(t.taskType),u=r.indexOf(a.taskType),i=c>=0?c:Number.MAX_SAFE_INTEGER,s=u>=0?u:Number.MAX_SAFE_INTEGER;return i-s})}function k(n,e,r){const t=p(n,e),a=t.findIndex(c=>c.id===r);return a>=0?t[a+1]:void 0}function f(n,e){switch(n){case"receiving":return e(["Receiving","استلام"]);case"qc":return e(["Quality check","فحص الجودة"]);case"putaway":return e(["Putaway","تخزين"]);case"putaway_quarantine":return e(["Putaway (quarantine)","تخزين (حجر صحي)"]);case"pick":return e(["Pick","التقاط"]);case"pack":return e(["Pack","تغليف"]);case"dispatch":return e(["Dispatch","إرسال"]);case"routing":return e(["Routing","توجيه"]);default:return n.replace(/_/g," ")}}function d(n,e){return e?`/tasks/${n}?companyId=${encodeURIComponent(e)}`:`/tasks/${n}`}export{k as f,f as p,d as t};
